<section class="panel expedicao-panel" data-tab-panel="recebimento" hidden>
    <div class="expedicao-heading"><div><h2>Confirmação de entrega</h2><p>Selecione uma entrega própria e registre a assinatura do destinatário.</p></div></div>
    <div class="expedicao-table-wrap"><table class="data-table expedicao-table entrega-table"><thead><tr><th>Pedido</th><th>Loja</th><th>Romaneio</th><th>Volumes</th><th>Expedido em</th><th>Status</th><th></th></tr></thead><tbody>
    <?php if (!empty($aguardandoRecebimento)): foreach ($aguardandoRecebimento as $item): $pedidoEntrega=$item['pedido']??[]; $lojaEntrega=trim((string)($pedidoEntrega['cliente_nome_fantasia']??''))?:trim((string)($pedidoEntrega['cliente_razao_social']??'')); $dataEntrega=!empty($item['data_expedicao'])?strtotime((string)$item['data_expedicao']):false; ?>
        <tr><td><strong><?= $esc($pedidoEntrega['codigo']??'#'.($pedidoEntrega['id']??0)); ?></strong></td><td><span class="entrega-loja" title="<?= $esc($lojaEntrega); ?>"><?= $esc($lojaEntrega?:'Loja não identificada'); ?></span></td><td><?= $esc($item['romaneio']??'—'); ?></td><td><?= (int)($item['volumes']??1); ?></td><td><?php if($dataEntrega): ?><span class="expedicao-date"><strong><?= date('Y-m-d',$dataEntrega); ?></strong><small><?= date('H:i:s',$dataEntrega); ?></small></span><?php else: ?>—<?php endif; ?></td><td><span class="entrega-status"><svg viewBox="0 0 24 24"><path d="M3 6h11v11H3zM14 10h4l3 3v4h-7z"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/></svg>Expedido</span></td><td><button type="button" class="button button-primary entrega-open" data-entrega-id="<?= (int)$item['id']; ?>" data-entrega-pedido="<?= $esc($pedidoEntrega['codigo']??'#'.($pedidoEntrega['id']??0)); ?>">Entregar</button></td></tr>
    <?php endforeach; else: ?><tr><td colspan="7" class="expedicao-empty">Nenhuma entrega própria aguardando confirmação.</td></tr><?php endif; ?>
    </tbody></table></div>
</section>

<div class="entrega-modal" data-entrega-modal hidden><div class="entrega-modal__backdrop" data-entrega-close></div><section class="entrega-modal__dialog" role="dialog" aria-modal="true" aria-labelledby="entrega-modal-title"><header><div><h3 id="entrega-modal-title">Confirmar entrega</h3><p>Pedido <strong data-entrega-pedido-label></strong></p></div><button type="button" class="entrega-modal__close" data-entrega-close aria-label="Fechar">×</button></header><form method="post" class="entrega-form" data-base-action="<?= $esc($url('expedicao/recebimento')); ?>"><input type="hidden" name="expedicao_id"><label><span>Nome do recebedor</span><input type="text" name="recebedor_nome" maxlength="120" autocomplete="name" required placeholder="Nome de quem recebeu"></label><label><span>Assinatura do recebedor</span><span class="signature-box"><canvas data-entrega-signature></canvas><button type="button" class="button button-outline signature-clear" data-entrega-clear>Limpar</button></span><input type="hidden" name="assinatura_recebedor" data-entrega-signature-value><small class="signature-hint">Assine com o mouse ou toque sobre a linha.</small></label><footer><button type="button" class="button button-outline" data-entrega-close>Cancelar</button><button type="submit" class="button button-primary">Confirmar entrega</button></footer></form></section></div>

<style>
.entrega-table th,.entrega-table td{text-align:center!important;vertical-align:middle!important}.entrega-table thead th{font-size:10.6px!important}.entrega-table tbody td{font-size:13px!important;white-space:nowrap}.entrega-table th:nth-child(2),.entrega-table td:nth-child(2){width:170px;max-width:170px}.entrega-table tbody td:nth-child(2){height:46px!important;padding-top:6px!important;padding-bottom:6px!important;white-space:normal}.entrega-loja{display:-webkit-box;width:100%;height:32px;max-height:32px;margin:auto;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2;line-clamp:2;line-height:16px;overflow-wrap:anywhere;text-overflow:ellipsis}.entrega-loja.is-long{font-size:12px!important}.entrega-loja.is-very-long{font-size:11px!important;line-height:15px}.entrega-status{display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border-radius:999px;background:#e0f2fe;color:#0369a1;font-size:12px;font-weight:850}.entrega-status svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2.1;stroke-linecap:round;stroke-linejoin:round}.entrega-open{min-height:36px;padding:7px 13px}.entrega-modal{position:fixed;z-index:10020;inset:0;display:grid;place-items:center;padding:18px}.entrega-modal[hidden]{display:none}.entrega-modal__backdrop{position:absolute;inset:0;background:rgba(15,23,42,.68);backdrop-filter:blur(4px)}.entrega-modal__dialog{position:relative;width:min(560px,100%);max-height:calc(100dvh - 36px);overflow:auto;padding:24px;border-radius:24px;background:#fff;box-shadow:0 28px 80px rgba(15,23,42,.3)}.entrega-modal__dialog header{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:18px}.entrega-modal__dialog h3{margin:0 0 4px}.entrega-modal__dialog p{margin:0;color:var(--text-muted)}.entrega-modal__close{width:34px;height:34px;border:0;border-radius:10px;background:var(--surface-muted);font-size:24px;line-height:1;cursor:pointer}.entrega-form{display:grid;gap:16px}.entrega-form label{display:grid;gap:7px;font-size:.88rem;font-weight:800}.entrega-form input[type="text"]{width:100%;min-height:50px;padding:0 14px;border:1px solid var(--border);border-radius:13px;font:inherit;box-sizing:border-box}.entrega-form input[type="text"]:focus{outline:0;border-color:var(--primary);box-shadow:0 0 0 4px color-mix(in srgb,var(--primary) 13%,transparent)}.entrega-form .signature-box{min-height:180px}.entrega-form canvas{display:block;width:100%;height:178px;touch-action:none}.entrega-form footer{display:flex;justify-content:flex-end;gap:10px}.entrega-form footer .button{min-height:44px;justify-content:center}@media(max-width:600px){.entrega-modal{padding:10px}.entrega-modal__dialog{padding:18px}.entrega-form footer{display:grid;grid-template-columns:1fr 1fr}}
</style>
<script>
(()=>{document.querySelectorAll('.entrega-loja').forEach(loja=>{const tamanho=loja.textContent.trim().length;loja.classList.toggle('is-long',tamanho>34&&tamanho<=55);loja.classList.toggle('is-very-long',tamanho>55)});const modal=document.querySelector('[data-entrega-modal]'),form=modal?.querySelector('.entrega-form'),canvas=form?.querySelector('[data-entrega-signature]'),hidden=form?.querySelector('[data-entrega-signature-value]');if(!modal||!form||!canvas||!hidden)return;const ctx=canvas.getContext('2d');let drawing=false,ink=false;const resize=()=>{const rect=canvas.getBoundingClientRect(),ratio=devicePixelRatio||1;if(rect.width<10)return;canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);ctx.strokeStyle='#111827';ctx.lineWidth=2.2;ctx.lineCap='round';ctx.lineJoin='round'};const clear=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);hidden.value='';ink=false};const close=()=>{modal.hidden=true;document.body.style.overflow='';form.reset();clear()};document.querySelectorAll('[data-entrega-close]').forEach(button=>button.addEventListener('click',close));document.querySelectorAll('[data-entrega-id]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.entregaId;form.action=`${form.dataset.baseAction}/${encodeURIComponent(id)}`;form.elements.expedicao_id.value=id;modal.querySelector('[data-entrega-pedido-label]').textContent=button.dataset.entregaPedido||'';modal.hidden=false;document.body.style.overflow='hidden';requestAnimationFrame(()=>{resize();form.elements.recebedor_nome.focus()})}));const point=event=>{const rect=canvas.getBoundingClientRect();return{x:event.clientX-rect.left,y:event.clientY-rect.top}};canvas.addEventListener('pointerdown',event=>{event.preventDefault();drawing=true;ink=true;const p=point(event);ctx.beginPath();ctx.moveTo(p.x,p.y);canvas.setPointerCapture(event.pointerId)});canvas.addEventListener('pointermove',event=>{if(!drawing)return;const p=point(event);ctx.lineTo(p.x,p.y);ctx.stroke()});const save=()=>{if(!drawing)return;drawing=false;if(ink)hidden.value=canvas.toDataURL('image/png')};canvas.addEventListener('pointerup',save);canvas.addEventListener('pointercancel',save);form.querySelector('[data-entrega-clear]').addEventListener('click',clear);form.addEventListener('submit',event=>{if(!hidden.value){event.preventDefault();window.showAppToast?.('Faça a assinatura do recebedor.','error')}});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!modal.hidden)close()})})();
</script>
<script>(()=>{const form=document.querySelector('.entrega-form'),canvas=form?.querySelector('[data-entrega-signature]'),hidden=form?.querySelector('[data-entrega-signature-value]');if(!form||!canvas||!hidden)return;const persistir=()=>{const ctx=canvas.getContext('2d');if(!ctx||canvas.width<2||canvas.height<2)return false;try{const pixels=ctx.getImageData(0,0,canvas.width,canvas.height).data;let assinou=false;for(let index=3;index<pixels.length;index+=16){if(pixels[index]>0){assinou=true;break}}if(assinou)hidden.value=canvas.toDataURL('image/png');return assinou}catch(error){return Boolean(hidden.value)}};canvas.addEventListener('pointerup',persistir,true);canvas.addEventListener('pointercancel',persistir,true);document.addEventListener('submit',event=>{if(event.target===form)persistir()},true);document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)setTimeout(persistir,100)})})();</script>
<script>(()=>{const form=document.querySelector('.entrega-form'),canvas=form?.querySelector('[data-entrega-signature]'),hidden=form?.querySelector('[data-entrega-signature-value]'),submit=form?.querySelector('[type="submit"]');if(!form||!canvas||!hidden||!submit)return;const exportar=()=>{const ctx=canvas.getContext('2d');if(!ctx)return false;const pixels=ctx.getImageData(0,0,canvas.width,canvas.height).data;let assinou=false;for(let index=3;index<pixels.length;index+=16){if(pixels[index]>0){assinou=true;break}}if(!assinou)return false;const limite=900,escala=Math.min(1,limite/canvas.width),saida=document.createElement('canvas');saida.width=Math.max(1,Math.round(canvas.width*escala));saida.height=Math.max(1,Math.round(canvas.height*escala));saida.getContext('2d').drawImage(canvas,0,0,saida.width,saida.height);hidden.value=saida.toDataURL('image/png');return true};form.addEventListener('submit',async event=>{event.preventDefault();if(form.dataset.saving==='1')return;if(!exportar()){window.showAppToast?.('Faça a assinatura do recebedor antes de confirmar.','error');return}form.dataset.saving='1';submit.disabled=true;submit.setAttribute('aria-busy','true');try{const response=await fetch(form.action,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},body:new FormData(form)}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||'Não foi possível salvar a assinatura da entrega.');window.showAppToast?.('Entrega confirmada e assinatura salva.','success');window.location.assign(`${location.pathname}?tab=concluidos`)}catch(error){window.showAppToast?.(error.message||'Não foi possível salvar a assinatura da entrega.','error')}finally{delete form.dataset.saving;submit.disabled=false;submit.removeAttribute('aria-busy')}},true)})();</script>
<script>(()=>{const canvas=document.querySelector('[data-entrega-signature]'),hidden=document.querySelector('[data-entrega-signature-value]'),box=canvas?.closest('.signature-box');if(!canvas||!hidden||!box)return;let ativo=false,assinou=false,ultimo=null;const ctx=canvas.getContext('2d'),ponto=(clientX,clientY)=>{const rect=canvas.getBoundingClientRect(),scaleX=rect.width?canvas.width/rect.width:1,scaleY=rect.height?canvas.height/rect.height:1;return{x:(clientX-rect.left)*scaleX,y:(clientY-rect.top)*scaleY}},configurar=()=>{ctx.setTransform(1,0,0,1,0,0);ctx.strokeStyle='#111827';ctx.lineWidth=Math.max(3,(window.devicePixelRatio||1)*2.4);ctx.lineCap='round';ctx.lineJoin='round'},salvar=()=>{if(!assinou)return;hidden.value=canvas.toDataURL('image/png');box.classList.add('has-signature')},iniciar=(x,y,event)=>{event.preventDefault();event.stopImmediatePropagation();ativo=true;assinou=true;ultimo=ponto(x,y);configurar();ctx.beginPath();ctx.arc(ultimo.x,ultimo.y,ctx.lineWidth/2,0,Math.PI*2);ctx.fillStyle='#111827';ctx.fill();canvas.setPointerCapture?.(event.pointerId)},mover=(x,y,event)=>{if(!ativo)return;event.preventDefault();event.stopImmediatePropagation();const atual=ponto(x,y);configurar();ctx.beginPath();ctx.moveTo(ultimo.x,ultimo.y);ctx.lineTo(atual.x,atual.y);ctx.stroke();ultimo=atual},finalizar=event=>{if(!ativo)return;event?.preventDefault?.();event?.stopImmediatePropagation?.();ativo=false;ultimo=null;salvar()};canvas.addEventListener('pointerdown',event=>iniciar(event.clientX,event.clientY,event),true);canvas.addEventListener('pointermove',event=>mover(event.clientX,event.clientY,event),true);canvas.addEventListener('pointerup',finalizar,true);canvas.addEventListener('pointercancel',finalizar,true);canvas.addEventListener('lostpointercapture',finalizar,true);if(!window.PointerEvent){canvas.addEventListener('mousedown',event=>iniciar(event.clientX,event.clientY,event),true);window.addEventListener('mousemove',event=>mover(event.clientX,event.clientY,event),true);window.addEventListener('mouseup',finalizar,true);canvas.addEventListener('touchstart',event=>{const touch=event.touches[0];if(touch)iniciar(touch.clientX,touch.clientY,event)},{capture:true,passive:false});canvas.addEventListener('touchmove',event=>{const touch=event.touches[0];if(touch)mover(touch.clientX,touch.clientY,event)},{capture:true,passive:false});canvas.addEventListener('touchend',finalizar,{capture:true,passive:false})}document.addEventListener('submit',event=>{if(event.target?.classList?.contains('entrega-form'))salvar()},true)})();</script>
<style>.entrega-form .signature-box.has-signature{border-color:var(--primary)!important;box-shadow:0 0 0 3px color-mix(in srgb,var(--primary) 10%,transparent)}.entrega-form [data-entrega-signature]{position:relative!important;z-index:5!important;pointer-events:auto!important;touch-action:none!important;cursor:crosshair!important;user-select:none!important;-webkit-user-select:none!important}</style>
